'use client'

import { forwardRef, useMemo, type HTMLAttributes, type ReactNode } from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import { playHoverSound } from '@/lib/sound'

export interface BreadcrumbItem {
  label: ReactNode
  href?: string
  icon?: ReactNode
  title?: string
}

const breadcrumbVariants = cva('flex items-center', {
  variants: {
    variant: {
      default: '',
      muted: '',
    },
    size: {
      sm: 'text-[11px] gap-1',
      md: 'text-sm gap-1.5',
      lg: 'text-base gap-2',
    },
  },
  defaultVariants: {
    variant: 'default',
    size: 'md',
  },
})

export interface BreadcrumbsProps
  extends Omit<HTMLAttributes<HTMLElement>, 'color'>, VariantProps<typeof breadcrumbVariants> {
  items: BreadcrumbItem[]
  maxItems?: number
  separator?: ReactNode
  siteUrl?: string
  'aria-label'?: string
  listClassName?: string
}

const DefaultSeparator = () => (
  <span
    className="inline-flex translate-y-px shrink-0 items-center justify-center text-(--color-subtle)"
    aria-hidden="true"
  >
    <svg
      width="12"
      height="12"
      viewBox="0 0 12 12"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M4.5 2.5l3 3.5-3 3.5" />
    </svg>
  </span>
)

export const Breadcrumbs = forwardRef<HTMLElement, BreadcrumbsProps>(
  (
    {
      items,
      maxItems = 4,
      separator,
      siteUrl,
      'aria-label': ariaLabel = 'Breadcrumb',
      variant,
      size,
      className,
      listClassName,
      ...props
    },
    ref,
  ) => {
    const sep = separator ?? <DefaultSeparator />

    const { visibleItems, collapsedItems } = useMemo(() => {
      if (!maxItems || items.length <= maxItems) {
        return { visibleItems: items, collapsedItems: [] }
      }
      const keep = maxItems - 2
      return {
        visibleItems: [items[0], ...items.slice(-keep)],
        collapsedItems: items.slice(1, items.length - keep),
      }
    }, [items, maxItems])

    const hasEllipsis = collapsedItems.length > 0

    const jsonLd = useMemo(() => {
      if (!siteUrl) return null
      return {
        '@context': 'https://schema.org',
        '@type': 'BreadcrumbList',
        itemListElement: items.map((item, i) => ({
          '@type': 'ListItem',
          position: i + 1,
          name: typeof item.label === 'string' ? item.label : '',
          item: item.href ? `${siteUrl}${item.href}` : undefined,
        })),
      }
    }, [items, siteUrl])

    const renderItem = (item: BreadcrumbItem) => {
      const isLast = !item.href
      const content = (
        <span
          className={cn(
            breadcrumbVariants({ variant, size }),
            isLast
              ? 'font-medium text-(--color-fg)'
              : 'text-(--color-muted) transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none hover:text-(--color-fg)',
          )}
        >
          {item.icon && (
            <span className="shrink-0 [&_svg]:size-3.5 me-1.5" aria-hidden="true">
              {item.icon}
            </span>
          )}
          {item.label}
        </span>
      )

      if (isLast) {
        return (
          <span aria-current="page" title={item.title}>
            {content}
          </span>
        )
      }

      return (
        <a
          href={item.href}
          title={item.title}
          className="outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) focus-visible:ring-offset-1 focus-visible:ring-offset-(--color-bg) rounded-sm"
          onMouseEnter={() => playHoverSound()}
        >
          {content}
        </a>
      )
    }

    return (
      <>
        {jsonLd && (
          <script
            type="application/ld+json"
            dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd) }}
          />
        )}
        <nav ref={ref} aria-label={ariaLabel} className={className} {...props}>
          <ol className={cn('flex flex-wrap items-center', listClassName)}>
            {visibleItems.map((item, i) => {
              const elements: ReactNode[] = []
              if (hasEllipsis && i === 1) {
                elements.push(
                  <li key="ellipsis" className="flex items-center">
                    <button
                      type="button"
                      aria-label={`Show ${collapsedItems.length} hidden pages`}
                      className={cn(
                        'inline-flex items-center justify-center rounded-md squircle-corners text-(--color-muted) transition-colors duration-(--motion-dur-fast) motion-reduce:transition-none hover:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent)',
                        size === 'sm' && 'size-7',
                        size === 'lg' && 'size-10',
                      )}
                      onMouseEnter={() => playHoverSound()}
                    >
                      <svg
                        width="16"
                        height="16"
                        viewBox="0 0 16 16"
                        fill="currentColor"
                        aria-hidden="true"
                      >
                        <circle cx="3" cy="8" r="1.5" />
                        <circle cx="8" cy="8" r="1.5" />
                        <circle cx="13" cy="8" r="1.5" />
                      </svg>
                    </button>
                  </li>,
                )
                elements.push(
                  <li
                    key="sep-ellipsis"
                    role="presentation"
                    aria-hidden="true"
                    className="flex items-center"
                  >
                    {sep}
                  </li>,
                )
              }
              elements.push(
                <li key={`item-${i}`} className="flex items-center">
                  {renderItem(item)}
                </li>,
              )
              if (i < visibleItems.length - 1) {
                elements.push(
                  <li
                    key={`sep-${i}`}
                    role="presentation"
                    aria-hidden="true"
                    className="flex items-center"
                  >
                    {sep}
                  </li>,
                )
              }
              return elements
            })}
          </ol>
        </nav>
      </>
    )
  },
)
Breadcrumbs.displayName = 'Breadcrumbs'

export { breadcrumbVariants }

export function BreadcrumbsPreview() {
  return (
    <div className="flex items-center justify-center p-6">
      <div className="w-full max-w-md">
        <Breadcrumbs
          items={[
            { label: 'Home', href: '/' },
            { label: 'Components', href: '/components' },
            { label: 'Breadcrumbs' },
          ]}
        />
      </div>
    </div>
  )
}

'use client'

const MUTE_KEY = 'sound-muted'
const MUTE_EVENT = 'sound-mute-change'

let muted = false
if (typeof window !== 'undefined') {
  try {
    muted = localStorage.getItem(MUTE_KEY) === '1'
  } catch {}
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean) {
  muted = value
  if (typeof window !== 'undefined') {
    try {
      localStorage.setItem(MUTE_KEY, value ? '1' : '0')
    } catch {}
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void) {
  if (typeof window === 'undefined') return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener('storage', onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener('storage', onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === 'undefined') return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== 'undefined') {
  const unlock = () => {
    initAudio()
    window.removeEventListener('pointerdown', unlock)
    window.removeEventListener('keydown', unlock)
    window.removeEventListener('touchstart', unlock)
  }
  window.addEventListener('pointerdown', unlock, { passive: true })
  window.addEventListener('keydown', unlock, { passive: true })
  window.addEventListener('touchstart', unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.12, pitch = 1.2) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {}
}

export function playClickSound(volume = 0.2, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'triangle'
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {}
}

export function playTickSound(volume = 0.1, pitch = 1.5) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {}
}

export function playBounceSound(volume = 0.3, pitch = 1.0) {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = 'sine'
    osc.frequency.setValueAtTime(260 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(650 * pitch, now + 0.04)
    osc.frequency.exponentialRampToValueAtTime(190 * pitch, now + 0.14)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.14)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.14)

    const subOsc = ctx.createOscillator()
    const subGain = ctx.createGain()

    subOsc.type = 'triangle'
    subOsc.frequency.setValueAtTime(420 * pitch, now)
    subOsc.frequency.exponentialRampToValueAtTime(120 * pitch, now + 0.05)

    subGain.gain.setValueAtTime(volume * 0.7, now)
    subGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.05)

    subOsc.connect(subGain)
    subGain.connect(ctx.destination)

    subOsc.start(now)
    subOsc.stop(now + 0.05)
  } catch {}
}
